type Adaptor struct {
	name        string
	port        string
	connected   bool
	adaptorType string
}

func NewAdaptor(name string, adaptorType string, v ...interface{}) *Adaptor {
	if name == "" {
		name = fmt.Sprintf("%X", Rand(int(^uint(0)>>1)))
	}

	a := &Adaptor{
		adaptorType: adaptorType,
		name:        name,
		port:        "",
	}

	for i := range v {
		switch v[i].(type) {
		case string:
			a.port = v[i].(string)
		}
	}

